#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Teste real do acesso a Sequências (ticket 01 de .scratch/canais-cadencia-backend):
# prepara um projeto Supabase para o login por link e provisiona as personas do teste.
#
# Rode num terminal interativo (de qualquer pasta do repositório):
#   scripts/wizard-teste-real.sh
# Para outro projeto: SUPABASE_REF=<ref> scripts/wizard-teste-real.sh
# No Windows, rode pelo Git Bash: o Windows PowerShell não executa .sh.
#
# Grava tudo em projeto-althius-frontend/.env.local, que o git ignora. Só as chaves
# VITE_* chegam ao navegador; as TESTE_* ficam locais para os testes. Rodar de novo
# reaproveita o que já foi salvo, inclusive as senhas das personas.

TOTAL_STAGES=11

RAIZ="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$RAIZ"
ENV_FILE="projeto-althius-frontend/.env.local"
SUPABASE_REF="${SUPABASE_REF:-ycbdilsmydvzezhlymty}"
PAINEL="https://supabase.com/dashboard/project/$SUPABASE_REF"
RE_EMAIL='^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
RE_UUID='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
SMTP_PROPRIO=0
USADOS="|"

[[ -t 0 ]] || { printf 'Rode este wizard num terminal interativo.\n' >&2; exit 1; }

# nova_senha imprime uma senha aleatória com minúscula, maiúscula, dígito e símbolo.
nova_senha() {
  local s
  s=$(LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom 2>/dev/null | head -c 20 || true)
  [[ ${#s} -eq 20 ]] || s=$(openssl rand -hex 10)
  printf '%sAa9-' "$s"
}

# novo_uuid imprime um UUID v4 em minúsculas.
novo_uuid() {
  if command -v uuidgen >/dev/null 2>&1; then
    uuidgen | tr '[:upper:]' '[:lower:]'
  elif [[ -r /proc/sys/kernel/random/uuid ]]; then
    cat /proc/sys/kernel/random/uuid
  else
    local h
    h=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')
    printf '%s-%s-4%s-%x%s-%s\n' "${h:0:8}" "${h:8:4}" "${h:13:3}" \
      "$(( (16#${h:16:1} & 3) | 8 ))" "${h:17:3}" "${h:20:12}"
  fi
}

# workspace_salvo KEY devolve o UUID já salvo em KEY ou um novo.
workspace_salvo() {
  local id
  id=$(_existing "$1" || true)
  [[ "$id" =~ $RE_UUID ]] || id=$(novo_uuid)
  printf '%s' "$id"
}

# copiar TEXTO põe o texto na área de transferência; falha se não houver como.
copiar() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# identidade CHAVE "Nome" apelido "o que ela testa" cria uma persona no Supabase Auth.
# Grava e-mail e senha antes de a pessoa ser criada, para uma nova rodada reusar a mesma senha.
identidade() {
  local var_email="TESTE_${1}_EMAIL" var_senha="TESTE_${1}_SENHA" email senha
  stage "Identidade · $2"
  say "$4"
  if [[ "$1" == RESPONSAVEL && "$SMTP_PROPRIO" == 0 ]]; then
    note "Sem SMTP próprio, só o e-mail com que você entra no Supabase recebe o link: use-o aqui."
  elif [[ "$SMTP_PROPRIO" == 1 ]]; then
    note "Apelidos da mesma caixa funcionam, ex.: voce+$3@seu-dominio."
  fi
  while :; do
    ask "$var_email" "E-mail:"
    email=$(printf '%s' "${!var_email}" | tr '[:upper:]' '[:lower:]')
    if [[ ! "$email" =~ $RE_EMAIL ]]; then
      warn "E-mail inválido."
    elif [[ "$USADOS" == *"|$email|"* ]]; then
      warn "Esse e-mail já é de outra persona; cada uma precisa do seu."
    else
      break
    fi
  done
  USADOS="$USADOS$email|"
  senha=$(_existing "$var_senha" || true)
  [[ -n "$senha" ]] || senha=$(nova_senha)
  printf -v "$var_email" '%s' "$email"
  write_env "$var_email" "$email"
  write_env "$var_senha" "$senha"
  open_url "$PAINEL/auth/users"
  step "Clique em Add user → Create new user."
  step "Email:    $email"
  step "Password: $senha"
  step "Marque Auto Confirm User e crie o usuário."
  note "Se essa pessoa já existe de uma rodada anterior, só siga."
  pause "Tecle Enter depois de criar"
}

banner "Teste real do Althius no Supabase"

stage "Chave publicável do Supabase"
say "O app precisa só da URL do projeto e da chave publicável; as duas são públicas."
open_url "$PAINEL/settings/api-keys"
note "Se o painel disser que o projeto não existe, você está na conta errada do Supabase."
step "Em API Keys, copie a Publishable key (começa com sb_publishable_)."
note "Se não houver chave publicável, crie uma nessa mesma página."
warn "Nunca use a Secret key (sb_secret_) nem a service_role: elas não vão para o frontend."
while :; do
  ask VITE_SUPABASE_PUBLISHABLE_KEY "Cole a chave publicável:"
  case "$VITE_SUPABASE_PUBLISHABLE_KEY" in
    sb_publishable_replace_me) warn "Esse é o valor de exemplo do .env.example." ;;
    sb_publishable_?*) break ;;
    sb_secret_*) warn "Essa é a chave secreta. Descarte a cópia e cole a publicável." ;;
    *) warn "A chave publicável começa com sb_publishable_." ;;
  esac
done
write_env VITE_SUPABASE_URL "https://$SUPABASE_REF.supabase.co"
write_env VITE_SUPABASE_PUBLISHABLE_KEY "$VITE_SUPABASE_PUBLISHABLE_KEY"

stage "Redirect URLs do Auth"
say "O link de acesso volta para o endereço que a pessoa tentou abrir. Fora da lista,"
say "o Supabase descarta esse caminho e abre a Site URL."
open_url "$PAINEL/auth/url-configuration"
step "Em Redirect URLs, adicione http://localhost:5173/** e salve."
step "Se o app já tem endereço publicado, adicione também https://<endereço>/**."
note "O ** aceita qualquer caminho do app, não só a raiz."
pause "Tecle Enter depois de salvar"

stage "SMTP próprio · domínio e chave no Resend"
say "Sem SMTP próprio, o Supabase só entrega e-mail para a equipe da organização no"
say "Supabase (os outros endereços dão 'Email address not authorized'), com limite"
say "baixo por hora. Dá para pular: aí só o seu e-mail da equipe recebe o link."
if confirm "Usar SMTP próprio (configurar agora ou já configurado)? Precisa de domínio verificado no Resend."; then
  SMTP_PROPRIO=1
  note "Se já configurou numa rodada anterior, só tecle Enter até a etapa das identidades."
  open_url "https://resend.com/domains"
  step "Confira que o domínio de envio está Verified. Se não estiver, adicione-o,"
  step "publique os registros DNS que o Resend mostrar e espere a verificação."
  pause "Tecle Enter com o domínio verificado"
  open_url "https://resend.com/api-keys"
  step "Crie uma API key com permissão Sending access e copie (começa com re_)."
  note "Ela não fica salva aqui: você cola direto no Supabase na próxima etapa."
  pause "Tecle Enter com a chave copiada"
else
  SKIPPED+=("SMTP próprio: sem ele, só e-mails da equipe da organização no Supabase recebem o link")
fi

stage "SMTP próprio · formulário no Supabase"
if [[ "$SMTP_PROPRIO" == 1 ]]; then
  open_url "$PAINEL/auth/smtp"
  step "Ative o SMTP personalizado e preencha:"
  say "    e-mail do remetente   um endereço do domínio verificado (ex.: nao-responda@seu-dominio)"
  say "    nome do remetente     Althius"
  say "    host                  smtp.resend.com"
  say "    porta                 465"
  say "    usuário               resend"
  say "    senha                 a API key do Resend (re_…)"
  step "Salve."
  note "Com SMTP próprio, o limite padrão é de 30 e-mails por hora (Auth → Rate Limits)."
  pause "Tecle Enter depois de salvar"
else
  note "Pulada: você escolheu seguir sem SMTP próprio."
  pause "Tecle Enter para seguir"
fi

identidade RESPONSAVEL "Vendedor responsável" responsavel \
  "Membro do Workspace A: cria e opera a única Sequência da Conta-alvo."
identidade MEMBRO "Outro Membro" membro \
  "Membro do Workspace A: vê a projeção, mas não altera nem cria Sequência concorrente."
identidade ADMIN "Administrador" admin \
  "Administrador do Workspace A: também não altera nem toma a responsabilidade."
identidade OUTRO_WS "Membro de outro Workspace" outro-workspace \
  "Membro do Workspace B: não vê a projeção do Workspace A."
identidade SEM_PARTICIPACAO "Sem Participação" sem-participacao \
  "Autenticado sem Participação ativa: o app mostra 'Nenhum Workspace ativo'."

stage "Participações nos Workspaces"
say "Cria os Workspaces da empresa A e B e as Participações:"
say "Workspace A: Vendedor responsável, Outro Membro e Administrador."
say "Workspace B: Membro de outro Workspace. Sem Participação fica sem linha, de propósito."
WS_A=$(workspace_salvo TESTE_WORKSPACE_A)
WS_B=$(workspace_salvo TESTE_WORKSPACE_B)
write_env TESTE_WORKSPACE_A "$WS_A"
write_env TESTE_WORKSPACE_B "$WS_B"
# Só ASCII no SQL: o clip.exe do Windows estraga acentos ao copiar.
SQL="do \$\$
begin
  if to_regclass('public.workspaces') is not null then
    insert into public.workspaces (id, name, type) values
      ('$WS_A'::uuid, 'Teste real - Workspace A', 'company'),
      ('$WS_B'::uuid, 'Teste real - Workspace B', 'company')
    on conflict (id) do nothing;
  end if;
end \$\$;

insert into public.workspace_memberships (workspace_id, user_id, role, active)
select v.workspace_id, u.id, v.role, true
from (values
  ('$WS_A'::uuid, '$TESTE_RESPONSAVEL_EMAIL', 'member'),
  ('$WS_A'::uuid, '$TESTE_MEMBRO_EMAIL', 'member'),
  ('$WS_A'::uuid, '$TESTE_ADMIN_EMAIL', 'admin'),
  ('$WS_B'::uuid, '$TESTE_OUTRO_WS_EMAIL', 'member')
) as v(workspace_id, email, role)
join auth.users u on lower(u.email) = v.email
on conflict (workspace_id, user_id) do update set role = excluded.role, active = true
returning workspace_id, user_id, role, active;"
open_url "$PAINEL/sql/new"
if copiar "$SQL"; then
  step "O SQL abaixo já está na área de transferência: cole no editor e clique em Run."
else
  step "Copie o SQL abaixo, cole no editor e clique em Run."
fi
printf '\n%s\n\n' "$SQL"
step "O resultado deve ter 4 linhas. Com menos, algum e-mail não bate com o usuário criado."
pause "Tecle Enter com as 4 linhas"

stage "Primeiro acesso no app"
PASTA_APP="$RAIZ/projeto-althius-frontend"
command -v cygpath >/dev/null 2>&1 && PASTA_APP=$(cygpath -w "$PASTA_APP" 2>/dev/null || printf '%s' "$PASTA_APP")
say "Em outro terminal, entre na pasta do app e rode npm install e depois npm run dev"
say "(reinicie o app se ele já estava rodando):"
say "    $PASTA_APP"
note "Ele precisa ficar em http://localhost:5173, a URL cadastrada nas Redirect URLs."
pause "Tecle Enter com o app no ar"
open_url "http://localhost:5173"
step "Clique em 'Acessar tela de login Supabase'."
step "Informe $TESTE_RESPONSAVEL_EMAIL e clique em 'Enviar link de acesso'."
step "Abra o e-mail e clique no link: o topo deve mostrar 'Workspace operacional'."
confirm "Entrou no Workspace operacional?" \
  || SKIPPED+=("Primeiro acesso: confira Redirect URLs, entrega do e-mail e as participações")
if [[ "$SMTP_PROPRIO" == 1 ]]; then
  step "Clique em Sair e entre da mesma forma com $TESTE_SEM_PARTICIPACAO_EMAIL."
  confirm "Apareceu 'Nenhum Workspace ativo'?" \
    || SKIPPED+=("Bloqueio sem Participação não apareceu para $TESTE_SEM_PARTICIPACAO_EMAIL")
else
  SKIPPED+=("Bloqueio sem Participação: o link para $TESTE_SEM_PARTICIPACAO_EMAIL só chega com SMTP próprio")
fi

finish
note "Próximo passo: o teste do ticket 01 (.scratch/canais-cadencia-backend/issues/01-acesso-real-e-responsabilidade-exclusiva.md)."
printf '\n'
